package com.travbook.stays.domain.model;
import com.travbook.hotels.domain.model.*;
import com.travbook.shared.domain.DomainFailure;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class Stay {
 private Stay(){}
 public enum CollectionMethod {PAY_NOW,PAY_AT_PROPERTY}
 public enum AmendmentState {PENDING,APPLIED,REJECTED}
 public record Amendment(UUID id,Quote quote,AmendmentState state,boolean responseLoss,Instant requestedAt){}
 public enum Scenario {SUCCESS,AUTH_DECLINED,RESERVATION_REJECTED,CAPTURE_DECLINED,RESERVATION_RESPONSE_LOST,CAPTURE_RESPONSE_LOST}
 public enum SpecialRequest {NONE,LATE_ARRIVAL}
 public enum Status {PROCESSING,CONFIRMED,FAILED,CANCELLATION_PENDING,CANCELLED,REVIEW}
 public enum Payment {NOT_STARTED,AUTHORIZED,CAPTURED,DECLINED,VOIDED,DEFERRED}
 public enum Reservation {NOT_STARTED,CONFIRMED,REJECTED,CANCELLED}
 public enum Refund {NONE,PENDING,SUCCEEDED,NOT_DUE}
 public enum Step {VALIDATE,AUTHORIZE,RESERVE,CAPTURE,CANCEL,VOID,REFUND,REFUND_STATUS,AMEND,CHANGE_VALIDATE,CHANGE_AUTHORIZE,CHANGE_CAPTURE,CHANGE_RESERVE,CHANGE_VOID,CHANGE_REFUND,CHANGE_REFUND_STATUS,DONE,REVIEW}
 public record Selection(HotelProperty property,HotelCriteria criteria,List<HotelOffer> offers,HotelMoney previousTotal,HotelMoney total,Instant checkedAt,Instant expiresAt){public Selection{offers=List.copyOf(offers);if(offers.isEmpty()||offers.stream().map(o->o.paymentCondition()).distinct().count()!=1)throw new IllegalArgumentException("Mixed collection terms");}}
 public record Quote(UUID id,UUID owner,int version,Selection selection,Instant createdAt,Instant expiresAt){
  public Quote{if(id==null||owner==null||version!=1||!expiresAt.isAfter(createdAt)||expiresAt.isAfter(selection.expiresAt()))throw new IllegalArgumentException("Invalid stay quote");}
  public CollectionMethod collectionMethod(){return selection.offers().getFirst().paymentCondition().equals("MOCK_PAY_AT_PROPERTY")?CollectionMethod.PAY_AT_PROPERTY:CollectionMethod.PAY_NOW;}
  public HotelMoney changeCharge(){return collectionMethod()==CollectionMethod.PAY_NOW?selection.total():HotelMoney.inr(BigDecimal.ZERO);}
  public HotelMoney changeRefund(){return collectionMethod()==CollectionMethod.PAY_NOW?selection.previousTotal():HotelMoney.inr(BigDecimal.ZERO);}
  public Instant checkIn(){return selection.criteria().checkIn().atTime(LocalTime.parse(selection.property().checkInTime())).atZone(ZoneId.of(selection.property().timezone())).toInstant();}
  public Instant effectiveExpiry(){return expiresAt.isBefore(checkIn())?expiresAt:checkIn();}
  public boolean expired(Instant now){return !effectiveExpiry().isAfter(now);}
  public void valid(Instant now){if(expired(now))throw new DomainFailure(QUOTE_EXPIRED,"This hotel quote expired. Request and accept a fresh quote.");}
 }
 public record Guest(int roomIndex,String givenName,String familyName,LocalDate dateOfBirth){public Guest{if(roomIndex<0||roomIndex>3||givenName==null||familyName==null||dateOfBirth==null)throw new DomainFailure(VALIDATION_FAILED,"Guest details are required.");givenName=java.text.Normalizer.normalize(givenName,java.text.Normalizer.Form.NFC).replaceAll("[\\s\\p{Zs}]+"," ").strip();familyName=java.text.Normalizer.normalize(familyName,java.text.Normalizer.Form.NFC).replaceAll("[\\s\\p{Zs}]+"," ").strip();if(givenName.codePoints().noneMatch(Character::isLetter)||familyName.codePoints().noneMatch(Character::isLetter)||!givenName.matches("[\\p{L}\\p{M} .’'-]{1,60}")||!familyName.matches("[\\p{L}\\p{M} .’'-]{1,60}"))throw new DomainFailure(VALIDATION_FAILED,"Use valid guest names, up to 60 characters.");}}
 public static void guests(Quote q,List<Guest> guests){
  if(guests==null||guests.isEmpty()||guests.size()>20)throw new DomainFailure(VALIDATION_FAILED,"Provide every guest in the quoted rooms.");
  var seen=new HashSet<String>();for(var g:guests){if(g.dateOfBirth().isAfter(q.selection().criteria().checkIn())||g.roomIndex()>=q.selection().criteria().rooms().size()||!seen.add((g.givenName()+":"+g.familyName()+":"+g.dateOfBirth()).toLowerCase(Locale.ROOT)))throw new DomainFailure(VALIDATION_FAILED,"Each guest must appear once in a quoted room with a valid birth date.");}
  for(int room=0;room<q.selection().criteria().rooms().size();room++){final int r=room;var ages=guests.stream().filter(g->g.roomIndex()==r).map(g->Period.between(g.dateOfBirth(),q.selection().criteria().checkIn()).getYears()).toList();var occupancy=q.selection().criteria().rooms().get(room);if(ages.stream().anyMatch(a->a<0||a>120)||ages.stream().filter(a->a>=18).count()!=occupancy.adults()||!ages.stream().filter(a->a<18).sorted().toList().equals(occupancy.childAges().stream().sorted().toList()))throw new DomainFailure(VALIDATION_FAILED,"Guest ages at check-in must match each room's quoted adults and child ages.");}
 }
 public record CancellationQuote(UUID id,UUID bookingId,UUID owner,long bookingVersion,HotelMoney refundAmount,HotelMoney retainedAmount,Instant createdAt,Instant expiresAt){}
 public record Cancellation(CancellationQuote quote,boolean simulateDelay,boolean simulateResponseLoss,UUID commandId){}
 public record Booking(UUID id,Quote quote,Instant acceptedAt,List<Guest> guests,SpecialRequest specialRequest,Scenario scenario,UUID commandId,UUID correlationId,
                       long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,
                       String supplierReference,String paymentReference,String refundReference,String failureCode,Cancellation cancellation,List<Amendment> amendments,List<StayChange> changes){
  public Booking{guests=List.copyOf(guests);amendments=List.copyOf(amendments);changes=List.copyOf(changes);if(amendments.size()>10)throw new IllegalArgumentException("Amendment limit");if(status==Status.CONFIRMED&&(!(payment==Payment.CAPTURED&&quote.collectionMethod()==CollectionMethod.PAY_NOW||payment==Payment.DEFERRED&&quote.collectionMethod()==CollectionMethod.PAY_AT_PROPERTY)||reservation!=Reservation.CONFIRMED)||status==Status.CANCELLED&&reservation!=Reservation.CANCELLED)throw new IllegalArgumentException("Invalid independent hotel states");}
  public Booking(UUID id,Quote quote,Instant acceptedAt,List<Guest> guests,SpecialRequest specialRequest,Scenario scenario,UUID commandId,UUID correlationId,long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,Cancellation cancellation){this(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version,createdAt,updatedAt,status,payment,reservation,refund,step,supplierReference,paymentReference,refundReference,failureCode,cancellation,List.of());}
  public Booking(UUID id,Quote quote,Instant acceptedAt,List<Guest> guests,SpecialRequest specialRequest,Scenario scenario,UUID commandId,UUID correlationId,long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,String supplierReference,String paymentReference,String refundReference,String failureCode,Cancellation cancellation,List<Amendment> amendments){this(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version,createdAt,updatedAt,status,payment,reservation,refund,step,supplierReference,paymentReference,refundReference,failureCode,cancellation,amendments,List.of());}
  public static Booking create(UUID id,Quote q,Instant accepted,List<Guest> guests,SpecialRequest request,Scenario scenario,UUID command,UUID correlation,Instant now){Stay.guests(q,guests);q.valid(now);if(q.collectionMethod()==CollectionMethod.PAY_AT_PROPERTY&&!Set.of(Scenario.SUCCESS,Scenario.RESERVATION_REJECTED,Scenario.RESERVATION_RESPONSE_LOST).contains(scenario))throw new DomainFailure(VALIDATION_FAILED,"This deferred stay has no platform payment scenario.");return new Booking(id,q,accepted,guests,request,scenario,command,correlation,1,now,now,Status.PROCESSING,Payment.NOT_STARTED,Reservation.NOT_STARTED,Refund.NONE,Step.VALIDATE,null,null,null,null,null,List.of());}
  public UUID operation(Step operation){if(operation==Step.AMEND)return amendments.getLast().id();return UUID.nameUUIDFromBytes((id+":"+operation.name()).getBytes(StandardCharsets.UTF_8));}
  public boolean terminal(){return step==Step.DONE||step==Step.REVIEW;}
  private void require(Step expected){if(step!=expected)throw new DomainFailure(BOOKING_CONFLICT,"Hotel workflow step mismatch.");}
  private Booking next(Status s,Payment p,Reservation r,Refund f,Step next,String supplier,String pay,String ref,String failure,Cancellation cancel,Instant now){return new Booking(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version+1,createdAt,now,s,p,r,f,next,supplier,pay,ref,failure,cancel,amendments,changes);}
  public Booking validated(Instant now){require(Step.VALIDATE);quote.valid(now);return next(status,deferred()?Payment.DEFERRED:payment,reservation,refund,deferred()?Step.RESERVE:Step.AUTHORIZE,supplierReference,paymentReference,refundReference,null,cancellation,now);}
  public Booking authorized(boolean ok,String ref,Instant now){require(Step.AUTHORIZE);return next(ok?status:Status.FAILED,ok?Payment.AUTHORIZED:Payment.DECLINED,reservation,refund,ok?Step.RESERVE:Step.DONE,supplierReference,ref,refundReference,ok?null:"AUTH_DECLINED",cancellation,now);}
  public Booking reserved(boolean ok,String ref,Instant now){require(Step.RESERVE);if(deferred())return next(ok?Status.CONFIRMED:Status.FAILED,Payment.DEFERRED,ok?Reservation.CONFIRMED:Reservation.REJECTED,refund,Step.DONE,ref,null,null,ok?null:"RESERVATION_REJECTED",cancellation,now);return next(status,payment,ok?Reservation.CONFIRMED:Reservation.REJECTED,refund,ok?Step.CAPTURE:Step.VOID,ref,paymentReference,refundReference,ok?null:"RESERVATION_REJECTED",cancellation,now);}
  public Booking captured(boolean ok,String ref,Instant now){require(Step.CAPTURE);return next(ok?Status.CONFIRMED:status,ok?Payment.CAPTURED:Payment.AUTHORIZED,reservation,refund,ok?Step.DONE:Step.CANCEL,supplierReference,ref,refundReference,ok?null:"CAPTURE_DECLINED",cancellation,now);}
  public CancellationQuote cancellationQuote(UUID qid,Instant now){var quote=currentQuote();if(status!=Status.CONFIRMED||!quote.checkIn().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Only confirmed stays before local check-in can be cancelled.");BigDecimal amount=BigDecimal.ZERO;Instant expiry=now.plusSeconds(300).isBefore(quote.checkIn())?now.plusSeconds(300):quote.checkIn();for(var room:quote.selection().offers()){if(!deferred()&&room.freeCancellationUntil()!=null&&room.freeCancellationUntil().isAfter(now)){amount=amount.add(room.total().amount());if(room.freeCancellationUntil().isBefore(expiry))expiry=room.freeCancellationUntil();}}return new CancellationQuote(qid,id,quote.owner(),version,HotelMoney.inr(amount),HotelMoney.inr(deferred()?BigDecimal.ZERO:quote.selection().total().amount().subtract(amount)),now,expiry);}
  public Booking cancel(Cancellation c,Instant now){if(status!=Status.CONFIRMED||c.quote().bookingVersion()!=version||!c.quote().expiresAt().isAfter(now)||!currentQuote().checkIn().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Cancellation quote expired or the booking changed. Review a fresh quote.");return next(Status.CANCELLATION_PENDING,payment,reservation,Refund.NONE,Step.CANCEL,supplierReference,paymentReference,null,null,c,now);}
  public Booking cancelled(Instant now){require(Step.CANCEL);boolean customer=cancellation!=null;boolean due=customer&&cancellation.quote().refundAmount().amount().signum()>0;return next(customer?Status.CANCELLED:Status.PROCESSING,payment,Reservation.CANCELLED,customer?(due?Refund.PENDING:Refund.NOT_DUE):Refund.NONE,customer?(due?Step.REFUND:Step.DONE):Step.VOID,supplierReference,paymentReference,refundReference,failureCode,cancellation,now);}
  public Booking voided(Instant now){require(Step.VOID);return next(Status.FAILED,Payment.VOIDED,reservation,refund,Step.DONE,supplierReference,paymentReference,refundReference,failureCode,cancellation,now);}
  public Booking refundSubmitted(String ref,boolean complete,Instant now){if(step!=Step.REFUND&&step!=Step.REFUND_STATUS)throw new DomainFailure(BOOKING_CONFLICT,"Unexpected refund state.");return next(Status.CANCELLED,payment,reservation,complete?Refund.SUCCEEDED:Refund.PENDING,complete?Step.DONE:Step.REFUND_STATUS,supplierReference,paymentReference,ref,failureCode,cancellation,now);}
  public Booking failBeforeEffect(String code,Instant now){if(step==Step.CAPTURE)return captured(false,paymentReference,now);if(step!=Step.VALIDATE&&step!=Step.AUTHORIZE)throw new IllegalStateException("Unknown effect must be reconciled");return next(Status.FAILED,payment,reservation,refund,Step.DONE,supplierReference,paymentReference,refundReference,code,cancellation,now);}
  public Booking resumeFrom(Booking checkpoint,Instant now){if(status!=Status.REVIEW||!id.equals(checkpoint.id())||checkpoint.version()+1!=version||checkpoint.step()==Step.REVIEW||checkpoint.terminal())throw new DomainFailure(BOOKING_CONFLICT,"No valid recovery checkpoint.");return new Booking(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version+1,createdAt,now,checkpoint.status(),checkpoint.payment(),checkpoint.reservation(),checkpoint.refund(),checkpoint.step(),checkpoint.supplierReference(),checkpoint.paymentReference(),checkpoint.refundReference(),checkpoint.failureCode(),checkpoint.cancellation(),amendments,changes);}
  public Booking reconcileLegacy(com.travbook.shared.domain.Recovery.Proof proof,Instant now){if(modern()||status!=Status.REVIEW||!proof.bookingId().equals(id)||proof.capturedAmount().compareTo(quote.selection().total().amount())!=0||!proof.paymentReference().equals("MOCK-PAY-"+id)||!proof.supplierReference().equals("MOCK-STAY-"+id))throw new DomainFailure(BOOKING_CONFLICT,"Legacy proof is not bound to this review.");boolean fulfilled=proof.outcome()==com.travbook.shared.domain.Recovery.Outcome.FULFILLED;if(fulfilled!=(cancellation==null)||fulfilled&&(proof.committedRefunds().signum()!=0||!proof.reservationState().equals("CONFIRMED"))||!fulfilled&&(!proof.reservationState().equals("CANCELLED")||proof.activeUnits()!=0||proof.settledRefunds().compareTo(cancellation.quote().refundAmount().amount())!=0))throw new DomainFailure(BOOKING_CONFLICT,"Legacy outcome is ambiguous.");return new Booking(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version+1,createdAt,now,fulfilled?Status.CONFIRMED:Status.CANCELLED,Payment.CAPTURED,Reservation.valueOf(proof.reservationState()),Refund.valueOf(proof.refundState()),Step.DONE,proof.supplierReference(),proof.paymentReference(),proof.refundReference(),null,cancellation,amendments,changes);}
  public Booking review(Instant now){return next(Status.REVIEW,payment,reservation,refund,Step.REVIEW,supplierReference,paymentReference,refundReference,"RECONCILIATION_REQUIRED",cancellation,now);}

  public boolean deferred(){return quote.collectionMethod()==CollectionMethod.PAY_AT_PROPERTY;}
  public boolean modern(){return deferred()||!amendments.isEmpty()||!changes.isEmpty();}
  public Quote currentQuote(){for(int i=changes.size()-1;i>=0;i--)if(changes.get(i).applied())return changes.get(i).quote();for(int i=amendments.size()-1;i>=0;i--)if(amendments.get(i).state()==AmendmentState.APPLIED)return amendments.get(i).quote();return quote;}
  public UUID documentRevision(){return currentQuote().id();}
  public Booking amend(Quote replacement,long expected,boolean loss,UUID command,Instant now){
   if(!changes.isEmpty()||!deferred()||status!=Status.CONFIRMED||step!=Step.DONE||version!=expected||amendments.size()>=10||!currentQuote().checkIn().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Only current confirmed deferred stays before check-in can be amended (maximum ten requests).");
   replacement.valid(now);var before=currentQuote().selection();var after=replacement.selection();
   if(!replacement.owner().equals(quote.owner())||replacement.collectionMethod()!=CollectionMethod.PAY_AT_PROPERTY||!before.property().id().equals(after.property().id())||!before.criteria().rooms().equals(after.criteria().rooms())||before.offers().size()!=after.offers().size())throw new DomainFailure(BOOKING_CONFLICT,"Keep the same property, deferred payment terms and room occupancy.");
   if(after.criteria().checkIn().isBefore(before.criteria().checkOut())&&before.criteria().checkIn().isBefore(after.criteria().checkOut()))throw new DomainFailure(BOOKING_CONFLICT,"This simulated supplier supports date moves that do not overlap the current stay.");
   for(int i=0;i<before.offers().size();i++)if(before.offers().get(i).planCode()!=after.offers().get(i).planCode()||!before.offers().get(i).supplier().equals(after.offers().get(i).supplier()))throw new DomainFailure(BOOKING_CONFLICT,"Keep the same supplier and room plan.");
   Stay.guests(replacement,guests);var history=new ArrayList<>(amendments);history.add(new Amendment(command,replacement,AmendmentState.PENDING,loss,now));
   return new Booking(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version+1,createdAt,now,Status.PROCESSING,payment,reservation,refund,Step.AMEND,supplierReference,paymentReference,refundReference,null,cancellation,history,changes);
  }
  public Booking amended(boolean accepted,Instant now){require(Step.AMEND);var history=new ArrayList<>(amendments);var a=history.removeLast();history.add(new Amendment(a.id(),a.quote(),accepted?AmendmentState.APPLIED:AmendmentState.REJECTED,a.responseLoss(),a.requestedAt()));return new Booking(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version+1,createdAt,now,Status.CONFIRMED,payment,reservation,refund,Step.DONE,supplierReference,paymentReference,refundReference,accepted?null:"AMENDMENT_REJECTED",cancellation,history,changes);}

  public List<Guest> currentGuests(){for(int i=changes.size()-1;i>=0;i--)if(changes.get(i).applied())return changes.get(i).guests();return guests;}
  public UUID currentPaymentId(){for(int i=changes.size()-1;i>=0;i--)if(changes.get(i).applied())return changes.get(i).id();return id;}
  public StayChange change(){return changes.getLast();}
  public void changeAllowed(long expected,Instant now){
   if(status!=Status.CONFIRMED||step!=Step.DONE||version!=expected||changes.size()+amendments.size()>=10||!currentQuote().checkIn().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Refresh a confirmed stay before check-in (maximum ten changes).");
   if(!deferred()&&currentQuote().selection().offers().stream().anyMatch(o->!o.refundable()||o.freeCancellationUntil()==null||!o.freeCancellationUntil().isAfter(now)))throw new DomainFailure(BOOKING_CONFLICT,"Prepaid changes require every current room to remain fully refundable.");
  }
  public Booking requestChange(Quote replacement,Instant accepted,List<Guest> replacementGuests,long expected,Scenario outcome,boolean delay,boolean loss,UUID command,Instant now){
   changeAllowed(expected,now);replacement.valid(now);if(!replacement.owner().equals(quote.owner())||replacement.collectionMethod()!=quote.collectionMethod()||!replacement.selection().property().id().equals(currentQuote().selection().property().id()))throw new DomainFailure(BOOKING_CONFLICT,"Keep the same property and payment method.");Stay.guests(replacement,replacementGuests);
   if(deferred()&&!Set.of(Scenario.SUCCESS,Scenario.RESERVATION_REJECTED,Scenario.RESERVATION_RESPONSE_LOST).contains(outcome))throw new DomainFailure(VALIDATION_FAILED,"Deferred changes have no payment simulation.");
   var c=new StayChange(command,replacement,currentQuote(),replacementGuests,accepted,now,currentPaymentId(),currentQuote().selection().total(),StayChange.State.PENDING,deferred()?Payment.DEFERRED:Payment.NOT_STARTED,Refund.NONE,outcome,delay,loss,null,null);
   var history=new ArrayList<>(changes);history.add(c);return withChanges(history,Status.PROCESSING,Step.CHANGE_VALIDATE,null,now);
  }
  private Booking withChanges(List<StayChange> history,Status state,Step step,String failure,Instant now){var c=history.getLast();return new Booking(id,quote,acceptedAt,guests,specialRequest,scenario,commandId,correlationId,version+1,createdAt,now,state,payment,reservation,refund,step,supplierReference,c.applied()&&!deferred()?c.paymentReference():paymentReference,refundReference,failure,cancellation,amendments,history);}
  private Booking progressChange(StayChange c,Status state,Step step,String failure,Instant now){var history=new ArrayList<>(changes);history.set(history.size()-1,c);return withChanges(history,state,step,failure,now);}
  public Booking failChangeBeforeEffect(Instant now){if(step==Step.CHANGE_CAPTURE)return changeResult(false,true,change().paymentReference(),now);if(step!=Step.CHANGE_VALIDATE&&step!=Step.CHANGE_AUTHORIZE)throw new IllegalStateException("Unknown change effect requires reconciliation");var c=change();return progressChange(c.progress(StayChange.State.REJECTED,c.payment(),Refund.NONE,c.paymentReference(),null),Status.CONFIRMED,Step.DONE,"CHANGE_QUOTE_UNAVAILABLE",now);}
  public Booking changeResult(boolean accepted,boolean completed,String reference,Instant now){var c=change();var state=c.state();var pay=c.payment();var ref=c.refund();String paymentRef=c.paymentReference(),refundRef=c.refundReference();Status status=Status.PROCESSING;Step next;String failure=null;
   switch(step){
    case CHANGE_VALIDATE->{if(!accepted){state=StayChange.State.REJECTED;status=Status.CONFIRMED;next=Step.DONE;failure="CHANGE_QUOTE_UNAVAILABLE";}else next=deferred()?Step.CHANGE_RESERVE:Step.CHANGE_AUTHORIZE;}
    case CHANGE_AUTHORIZE->{pay=accepted?Payment.AUTHORIZED:Payment.DECLINED;paymentRef=reference;if(accepted)next=Step.CHANGE_CAPTURE;else{state=StayChange.State.REJECTED;status=Status.CONFIRMED;next=Step.DONE;failure="CHANGE_AUTH_DECLINED";}}
    case CHANGE_CAPTURE->{pay=accepted?Payment.CAPTURED:Payment.AUTHORIZED;paymentRef=reference;next=accepted?Step.CHANGE_RESERVE:Step.CHANGE_VOID;}
    case CHANGE_VOID->{if(!accepted)throw new IllegalStateException("Unknown replacement void");pay=Payment.VOIDED;state=StayChange.State.REJECTED;status=Status.CONFIRMED;next=Step.DONE;failure="CHANGE_CAPTURE_DECLINED";}
    case CHANGE_RESERVE->{state=accepted?StayChange.State.RESERVED:StayChange.State.REJECTED;if(deferred()){state=accepted?StayChange.State.COMPLETED:StayChange.State.REJECTED;ref=Refund.NOT_DUE;status=Status.CONFIRMED;next=Step.DONE;failure=accepted?null:"CHANGE_REJECTED";}else{ref=Refund.PENDING;next=Step.CHANGE_REFUND;}}
    case CHANGE_REFUND,CHANGE_REFUND_STATUS->{refundRef=reference;ref=completed?Refund.SUCCEEDED:Refund.PENDING;next=completed?Step.DONE:Step.CHANGE_REFUND_STATUS;if(completed){status=Status.CONFIRMED;state=c.applied()?StayChange.State.COMPLETED:StayChange.State.COMPENSATED;failure=c.applied()?null:"CHANGE_REJECTED_AND_REFUNDED";}}
    default->throw new IllegalStateException("Unexpected change step");
   }
   return progressChange(c.progress(state,pay,ref,paymentRef,refundRef),status,next,failure,now);
  }
  public void voucherAllowed(){if(status!=Status.CONFIRMED||reservation!=Reservation.CONFIRMED||!(payment==Payment.CAPTURED||payment==Payment.DEFERRED&&deferred()))throw new DomainFailure(BOOKING_CONFLICT,"A voucher is available only for a currently confirmed stay.");}
 }
 public record Voucher(UUID id,UUID bookingId,Instant createdAt,String sha256,int byteLength,String content){}
}
